enum MediaKind {
  photo('photo'),
  video('video'),
  unknown('unknown');

  const MediaKind(this.value);

  /// The wire value.
  final String value;

  /// Unknown values never crash a client: they read as [unknown] (api-conventions section 2).
  static MediaKind fromJson(Object? v) {
    for (final e in values) {
      if (e.value == v) return e;
    }
    return MediaKind.unknown;
  }

  String toJson() => value;
}

